 @override
  Widget build(BuildContext context) {
    final responsive = ResponsiveFlutter.of(context);
    return Scaffold(
      backgroundColor: Customcolor.background,
      appBar: CommonAppBar(
        type: AppBarType.inner,
        title: CommonStrings.ourActivities,
        onBack: () => Navigator.pop(context),
        onSearch: () {},
        onShare: () {},
        shareLink: "",
      ),
      body: ListView(
        shrinkWrap: true,
        padding: EdgeInsets.zero,
        physics: ScrollPhysics(),
        children: [
          Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.start,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
               
                SmartHtmlWidget(
                    html:
                        'Merck Foundation Africa Asia Luminary 2025 Co-Chaired by The Gambia First Lady and Merck Foundation CEO and Inaugurated by the Gambia Vice President and Merck foundation Chairman',
                    textColor: Customcolor.colorVoilet,
                    fontSize: responsive.fontSize(3),
                    fontWeight: FontWeight.w600),
                8.0.heightBox,
                SmartHtmlWidget(
                  html:
                      '<p>&nbsp;</p>\r\n\r\n<p style=\"text-align: center;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><img src=\"https://merck-foundation.com/merckfoundation/public/assets/plugins/ckfinder/core/connector/php/connector.php?command=Proxy&amp;type=Files&amp;currentFolder=%2F&amp;fileName=Merck+Foundation+Africa+Asia+Luminary+2025.jpg\" style=\"width: 600px; height: 352px;\" /></span></span><br />\r\n<em><span style=\"color:#2980b9;\"><span style=\"font-size:9.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><b>Merck Foundation Chairman and CEO with The Gambia Vice President and First Lady, and First Ladies of Burundi, CAR, Liberia, Sao Tome, Senegal at Merck Foundation Africa Asia Luminary 2025</b></span></span></span></em></p>\r\n\r\n<ul>\r\n\t<li style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">First Ladies of Burundi, Central Africa, Liberia, S&atilde;o Tom&eacute; &amp; Pr&iacute;ncipe and Senegal attend 12th Merck Foundation Africa Asia Luminary, Co-chaired by The Gambia First Lady and Merck Foundation CEO. </span></span></span></span></b></span></span></span></li>\r\n\t<li style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">The 12th Edition of Merck Foundation Africa Asia Luminary was officially inaugurated by the Vice President of The Republic of The Gambia, Mr. MUHAMMAD B. S. JALLOW and Merck Foundation Chairman, Prof. Dr. Frank Stangenberg-Haverkamp. </span></span></span></span></b></span></span></span></li>\r\n\t<li style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">The conference was co-chaired by The First Lady of the Republic of The Gambia, H.E. Mrs. FATOUMATTA BAH-BARROW and Merck Foundation CEO, Senator, Dr. Rasha Kelej and attended by 7 African First Ladies as Guests of Honor.</span></span></span></span></b></span></span></span></li>\r\n\t<li style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">More than 6,000 healthcare providers, policymakers and media from over 70 English, French, Spanish and Portuguese speaking countries attended the Luminary through hybrid model to benefit from three parallel scientific and social sessions to advance healthcare capacity and awareness in 44 critical and underserved medical specialties. </span></span></span></span></b></span></span></span></li>\r\n\t<li style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">Merck Foundation celebrated the 13-year journey of their development programs, during 2025 Luminary.&nbsp;</span></span></span></span></b></span></span></span></li>\r\n\t<li style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">Link to Live Stream of Inaugural Session of Merck Foundation Africa Asia Luminary 2025 here: </span></span></span></span></b><a href=\"https://www.facebook.com/KelejRasha/videos/1336583331478575/?rdid=LUbwA6fHGdh4UlF1&amp;share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2Fv%2F165KwnvP6e%2F\" style=\"color:blue; text-decoration:underline\"><b><span style=\"line-height:150%\"><span verdana=\"\">https://www.facebook.com/share/v/16HsjMT7sN/</span></span></b></a></span></span></span></li>\r\n</ul>\r\n\r\n<p style=\"text-align: justify; margin: 0cm 0cm 8pt;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Merck Foundation, the philanthropic arm of Merck KGaA Germany, conducted the <b>12<sup>th</sup> Edition</b> of their annual conference, <b>&ldquo;Merck Foundation Africa Asia Luminary&rdquo;</b>, in partnership with the <b>Government of The Gambia</b>, on <b>14th and 15th October</b>, in <b>Banjul, The Gambia</b>. The conference was inaugurated by <b>Mr. MUHAMMAD B. S. JALLOW, Vice President of the Republic of The Gambia</b>, together with <b>Prof. Dr. Frank Stangenberg-Haverkamp, Chairman of Merck Foundation Board of Trustees</b>, and <b>co-chaired by Mrs. FATOUMATTA BAH-BARROW, The First Lady of Gambia and Ambassador of Merck Foundation More Than a Mother and Senator, Dr. Rasha Kelej (Ret.), CEO of Merck Foundation and President of More Than a Mother.</b> <b>The First Ladies of Africa</b>, who are also the <b>Ambassadors of Merck Foundation More Than a Mother</b> joined as the <b>Guests of Honor and Keynote Speakers.</b> </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">During the inauguration of the conference, <b>Mr. MUHAMMAD B. S. JALLOW, Vice President of the Republic of The Gambia</b> stated &ldquo;It is a great honor to inaugurate the Merck Foundation Africa Asia Luminary, being hosted here in The Gambia. I would also like to commend the close partnership between <b>The First Lady of Gambia and Merck Foundation Chairman and CEO</b>, since 2017, that continue to promote health, education, and empowerment across our nation and inspire hope for a better future&rdquo;.</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Senator, Dr. Rasha Kelej, CEO of Merck Foundation and Co-Chairperson of the 12<sup>th</sup> Edition of Merck Foundation Africa Asia Luminary</span></span></span></b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"> shared, &ldquo;I am delighted <b>to host our prestigious annual conference in The Gambia, </b>together with my dear sister and our long-term partner, <b>Mrs. FATOUMATTA BAH-BARROW, First Lady of The Gambia and Ambassador of Merck Foundation More Than a Mother.</b> </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">I am very happy that our conference was officially inaugurated by <b>Mr. MUHAMMAD B. S. JALLOW, Vice President of the Republic of The Gambia</b>, together with <b>Prof. Dr. Frank Stangenberg-Haverkamp, Chairman of Merck Foundation Board of Trustees. </b></span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Moreover, it was great welcoming our esteemed <b>Guests of Honor and Keynote Speakers, the First Ladies of African Countries</b>, also the <b>Ambassadors of the &ldquo;Merck Foundation More Than a Mother&rdquo;.</b> Together, we shared experiences and engaged in meaningful discussions on the impact of our programs, aimed at transforming patient care and raising awareness on a wide range of critical social and health issues.&quot;</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Mrs. FATOUMATTA BAH-BARROW, The First Lady of The Gambia, Ambassador of Merck Foundation More Than a Mother and Co-Chairperson of the 12<sup>th</sup> Edition of Merck Foundation Africa Asia Luminary</span></span></span></b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"> shared, &ldquo;It has been an honour to host the <b>12<sup>th</sup> Edition of Merck Foundation Africa Asia Luminary</b> in our country, inaugurated by <b>H.E. The Vice President of The Gambia</b>. It was an honor to welcome my dear sisters, <b>The First Ladies of Africa</b>, Ministers, Healthcare Experts, Media Representatives, and Delegates. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">I am proud of my partnership with Merck Foundation. They have provided <b>94 scholarships</b> for our local Gambian doctors in more than 30 critical and undeserved specialties. 30 underserved specialties. Together we are not only transforming our public healthcare landscape but also making history as many of these doctors are becoming first specialists in their fields. I am very proud of this great achievement.&rdquo;</span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin: 0cm 0cm 8pt; text-align: center;\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Watch the Merck Foundation Partnership Journey with The First Lady of The Gambia since 2017, here:</span></span></span></b></span></span></span></p>\r\n\r\n<div class=\"videoEmbed\" style=\"text-align: center;\"><iframe allowfullscreen=\"\" frameborder=\"0\" height=\"349\" mozallowfullscreen=\"\" src=\"https://www.youtube.com/embed/Doazw25BwhM\" webkitallowfullscreen=\"\" width=\"560\"></iframe></div>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Prof. Dr. Frank Stangenberg Haverkamp, Chairman of Merck Foundation Board of Trustees</span></span></span></b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"> added, &ldquo;I would like to thank <b>H.E. Mr. MUHAMMAD B. S. JALLOW, Vice President of The Republic of The Gambia</b>, and our long-term partner <b>H.E. Mrs. FATOUMATTA BAH-BARROW, The First Lady of The Gambia</b> for hosting our annual conference in the beautiful country of The Gambia. I would also like to thank the <b>First</b> <b>Ladies of Africa</b>, who joined as Guests of Honor, along with African Ministers, Health Experts, Policy Makers, Government Officials, Academia and Media for joining hands with us to realize the Merck Foundation&rsquo;s vision that <b>&lsquo;Everyone can lead a Healthy and Happy life&rsquo;.&rdquo;</b></span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><a name=\"_Hlk211375635\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">The First Ladies of African Countries, </span></span></span></b></a><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">who joined the <b>12<sup>th</sup> Edition of Merck Foundation Africa Asia Luminary</b> are: </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">H.E. Madam ANGELINE NDAYISHIMIYE, </span><span style=\"color:#c00000\">The First Lady of the Republic of Burundi</span></span></span></span></b></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">H.E. Madam BRIGITTE TOUADERA, </span><span style=\"color:#c00000\">The First Lady of Central African Republic </span></span></span></span></b></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">H.E. Mrs. KARTUMU YARTA BOAKAI, </span><span style=\"color:#c00000\">The First Lady of the Republic of Liberia</span></span></span></span></b></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">H.E. Mrs. MARIA DE FATIMA VILA NOVA, </span><span style=\"color:#c00000\">The First Lady of the Democratic Republic of S&atilde;o Tom&eacute; and Pr&iacute;ncipe</span></span></span></span></b></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\"><span style=\"color:#002060\">H.E. Madam MARIE KHONE FAYE,</span><span style=\"color:#c00000\"> First Lady of the Republic of Senegal</span></span></span></span></b></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><b><span lang=\"EN-GB\"><span style=\"line-height:150%\"><span verdana=\"\">Senator, Dr. Rasha Kelej stated, </span></span></span></b><span lang=\"EN-GB\"><span style=\"line-height:150%\"><span verdana=\"\">&ldquo;I am proud to share that Merck Foundation has provided more than <b>2400 scholarships for young doctors from 52 countries in 44 critical and underserved specialties</b>. </span></span></span><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Many of our Merck Foundation Alumni are becoming the first specialists in their countries. </span></span></span><span lang=\"EN-GB\"><span style=\"line-height:150%\"><span verdana=\"\">Together with our Ambassadors and Partners, we are making history and transforming the patient care landscape across Africa and beyond. </span></span></span><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Many of them are becoming the first specialists in their countries.&rdquo;</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">The conference was held in a hybrid format, featuring both physical and online participation of more than <b>6,000 healthcare providers, policymakers, academia, researchers, and media representatives</b> from over 70 countries across Africa, Asia, and beyond. Of these, over 300 participants attended in person.</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">During the <b>12<sup>th</sup> Edition of Merck Foundation Africa Asia Luminary</b>, an important occasion was marked; <b>13 years of Merck Foundation&rsquo;s </b>development programs that started in 2012. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">On the first day of the conference, the Plenary Session of the Merck Foundation Africa Asia Luminary 2025 took place, featuring keynote speeches of <b>First Ladies of Africa. </b></span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Moreover, a high-level ministerial panel<b> </b>discussion was also held with African Ministers. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">The Day 2 of the conference will have three key parallel scientific and community awareness sessions, covering topics such as diabetes and hypertension, medical capacity building in other specialties like respiratory care, acute care, emergency pediatric and neonatal care, and more, and Health Media Training, which will be conducted for African journalists. This session will emphasize the critical role of the media in influencing communities and driving cultural change, with regards to a wide range of social and health issues like Breaking Infertility Stigma, Supporting Girls&#39; Education, Stopping GBV, Ending Child Marriage &amp; FGM, Empowering Women, Diabetes and Hypertension Awareness. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Countries that physically participated in the 12<sup>th</sup> Edition of Merck Foundation Africa Asia Luminary included: </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Gabon, The Gambia, Ghana, India, Kenya, Liberia, Malawi, Mauritania, Mozambique, Nigeria, </span></span></span><span style=\"line-height:150%\"><span verdana=\"\">Rwanda, Senegal, Sierra Leone, and Uganda.</span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">Countries that participated virtually included:</span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><span lang=\"EN-GB\"><span style=\"line-height:150%\"><span verdana=\"\">Angola, Bangladesh, Benin, Botswana, Burkina Faso, Burundi, Cameroon, Canada, Central Africa Republic, Cambodia, Chad, C&ocirc;te d&#39;Ivoire, Republic of the Congo, Democratic Republic of the Congo, Egypt, Ethiopia, France, Germany, Guinea &ndash; Bissau, Guinea &ndash; Conakry, Indonesia, Lesotho, Malaysia, Mali, Mauritius, Mexico, Myanmar, Namibia, Nepal, Niger, Peru, Philippines, Russia, Somalia, South Africa, Sri Lanka, Sudan, Tanzania, Thailand, The Gambia, Togo, Tunisia, U.A.E, UK, US, Vietnam, Zambia, Zimbabwe and more. </span></span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><a name=\"_Hlk119931081\"><span lang=\"EN-US\"><span style=\"line-height:150%\"><span verdana=\"\">The <b>7<sup>th</sup> Edition of Merck Foundation First Ladies Initiative </b>is <b>streamed live on the social media handles of <u>Merck Foundation</u> and <u>Senator, Dr. Rasha Kelej,</u> CEO of Merck Foundation:</b></span></span></span></a></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 8pt\"><span style=\"font-size:11.0pt;\"><span style=\"font-family:Verdana,Geneva,sans-serif;\"><span style=\"line-height:150%\"><a name=\"_